// Validate required env vars
const required = [
  'KOMMO_BASE_URL', 'KOMMO_ACCESS_TOKEN', 'KOMMO_PIPELINE_ID',
  'KOMMO_STATUS_NOVO_SEGUIDOR', 'KOMMO_STATUS_INTERESSE_REAL',
  'KOMMO_STATUS_CONSULTA_AGENDADA', 'OPENAI_API_KEY', 'META_ACCESS_TOKEN'
];
const missing = required.filter(v => !$env[v]);
if (missing.length > 0) {
  throw new Error('Missing env vars: ' + missing.join(', '));
}
const item = $input.first();
item.json._execStart = Date.now();
item.json._execId = Math.random().toString(36).slice(2, 10);
return [item];

// Parse Instagram comment webhook and check for MUDANÇA keyword
const body = $input.first().json.body;
if (!body || !body.entry || !body.entry[0]) {
  return [{ json: { skip: true, reason: 'No entry in payload' } }];
}

const entry = body.entry[0];

// Only process comment events
if (!entry.changes || !entry.changes[0] || entry.changes[0].field !== 'comments') {
  return [{ json: { skip: true, reason: 'Not a comment event' } }];
}

const change = entry.changes[0];
const value = change.value;

if (!value || !value.text || !value.from) {
  return [{ json: { skip: true, reason: 'Missing comment data' } }];
}

const commentText = value.text.trim();
const senderId = String(value.from.id);
const senderUsername = value.from.username || 'ig_user_' + senderId;

// Check if comment contains MUDANÇA (case-insensitive, accent-insensitive)
const normalizedComment = commentText
  .toUpperCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const hasMudanca = normalizedComment.includes('MUDANCA');

if (!hasMudanca) {
  return [{ json: { skip: true, reason: 'Comment does not contain MUDANÇA' } }];
}

// Filter by specific reel media ID (optional — if MUDANCA_MEDIA_ID is set)
const targetMediaId = $env.MUDANCA_MEDIA_ID || '';
const commentMediaId = value.media ? String(value.media.id) : '';

if (targetMediaId && commentMediaId && commentMediaId !== targetMediaId) {
  return [{ json: { skip: true, reason: 'Comment not on target reel' } }];
}

// Deduplication: check if we already processed this user recently
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedUsers) staticData.processedUsers = {};

const now = Date.now();
const cooldownMs = 24 * 60 * 60 * 1000; // 24h cooldown per user
const lastProcessed = staticData.processedUsers[senderId];

if (lastProcessed && (now - lastProcessed) < cooldownMs) {
  return [{ json: { skip: true, reason: 'User already processed in last 24h' } }];
}

staticData.processedUsers[senderId] = now;

// Clean old entries (keep last 48h)
for (const uid of Object.keys(staticData.processedUsers)) {
  if (now - staticData.processedUsers[uid] > 2 * cooldownMs) {
    delete staticData.processedUsers[uid];
  }
}

return [{
  json: {
    skip: false,
    eventType: 'comment',
    senderId,
    senderUsername,
    commentText,
    mediaId: commentMediaId,
    timestamp: new Date().toISOString()
  }
}];

const response = $input.first().json;
const prevData = $('Parse & Filter MUDANÇA').first().json;
let contactId = null, contactExists = false, contactName = null;

if (response && response._embedded && response._embedded.contacts && response._embedded.contacts.length > 0) {
  const c = response._embedded.contacts[0];
  contactId = c.id;
  contactExists = true;
  contactName = c.name;
}

return [{ json: { ...prevData, contactId, contactExists, contactName } }];

const prevData = $('Contact Exists?').first().json;
let contactId = prevData.contactId, contactName = prevData.contactName;

if (!contactId) {
  const r = $input.first().json;
  if (r && r._embedded && r._embedded.contacts && r._embedded.contacts.length > 0) {
    contactId = r._embedded.contacts[0].id;
    contactName = r._embedded.contacts[0].name;
  }
}

if (!contactId) {
  return [{ json: { ...prevData, contactId: null, contactName: prevData.senderUsername, _contactFailed: true } }];
}

return [{ json: { ...prevData, contactId, contactName: contactName || prevData.senderUsername } }];

const prevData = $('Merge Contact Data').first().json;
if (prevData._contactFailed) {
  return [{ json: { ...prevData, leadId: null, leadExists: false, _leadSkipped: true } }];
}
const r = $input.first().json;
let leadId = null, leadExists = false;
if (r && r._embedded && r._embedded.leads && r._embedded.leads.length > 0) {
  leadId = r._embedded.leads[0].id;
  leadExists = true;
}
return [{ json: { ...prevData, leadId, leadExists } }];

const prevData = $('Lead Exists?').first().json;
let leadId = prevData.leadId;

if (!leadId) {
  const r = $input.first().json;
  if (r && r._embedded && r._embedded.leads && r._embedded.leads.length > 0) {
    leadId = r._embedded.leads[0].id;
  }
}

if (!leadId) {
  return [{ json: { ...prevData, leadId: null, _leadFailed: true } }];
}

return [{ json: { ...prevData, leadId } }];

// Generate personalized DM based on Be Healthy manual — MUDANÇA reel context
const data = $input.first().json;

const contactName = data.contactName || data.senderUsername || '';
const firstName = contactName.split(/[_\s.]/)[0];
// Capitalize first letter
const displayName = firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();

// System prompt based on Be Healthy manual + MUDANÇA reel context
const systemPrompt = `Você é a assistente de atendimento do Instituto Be Healthy (@dr.felipefranca).
Fale em português brasileiro. Seja empática, acolhedora e profissional.

CONTEXTO: A pessoa comentou "MUDANÇA" em um Reel do Dr. Felipe sobre transformação de saúde e bem-estar.
Isso é um sinal FORTE de interesse — ela quer mudar algo na vida dela (corpo, saúde, autoestima).

Seu objetivo é:
1. Acolher e validar o desejo de mudança
2. Usar o método SPIN para entender o que ela quer mudar
3. Conectar o desejo dela com os serviços do Instituto Be Healthy
4. Direcionar para agendar uma consulta oferecendo 2 horários

MÉTODO SPIN:
- Situação: "Como está sua relação com [saúde/corpo/autoestima] hoje?"
- Problema: "O que mais te incomoda ultimamente?"
- Implicação: "Isso tem impactado sua autoestima, rotina ou vida social?"
- Necessidade: "Se pudesse mudar uma coisa agora, o que seria?"

REGRAS:
- NUNCA dê conselhos médicos ou diagnósticos
- NUNCA prescreva medicamentos
- NUNCA prometa resultados específicos
- SEMPRE redirecione para consulta: "Essa é exatamente uma das coisas que o Dr. vai avaliar na sua consulta, de forma personalizada para o seu caso."
- Foque na TRANSFORMAÇÃO, não no procedimento
- Use o nome da pessoa
- NÃO use "agende sua consulta" — ofereça 2 horários com escassez

SERVIÇOS DISPONÍVEIS:
- Consulta Diagnóstica Integrativa (R$800) — Avaliação completa + Bioimpedância InBody + Plano personalizado
- MEP-6X — Protocolo de emagrecimento em 6 fases
- Fast Slim (Tirzepatida) — Emagrecimento com medicação
- Consulta Start (R$500) — Entrada acessível
- Modulação Hormonal — Cansaço, menopausa, libido
- Procedimentos Estéticos — Remodelação, celulite, protocolos corporais
- Soroterapia — Diversos protocolos IV

DIFERENCIAIS:
- Mais de 5 anos de experiência
- Satisfação acima de 95%
- Protocolos exclusivos e personalizados
- "Nada é genérico aqui. O Dr. monta um plano exclusivo para o seu caso."

Gere UMA mensagem de DM (máximo 3 parágrafos curtos). Seja natural, não robótica.
A mensagem deve:
1. Cumprimentar pelo nome e validar que ela quer mudança
2. Fazer UMA pergunta SPIN para entender o que ela quer mudar
3. Mencionar brevemente que o Instituto pode ajudar nessa transformação`;

const userMsg = `A pessoa @${data.senderUsername} (nome: ${displayName}) comentou "${data.commentText}" no Reel sobre mudança. Gere a DM personalizada.`;

// OpenAI call with retry
let aiResponse = null;
let lastError = null;

for (let attempt = 0; attempt < 2; attempt++) {
  try {
    const oResp = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + $env.OPENAI_API_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: $env.OPENAI_MODEL || 'gpt-4o',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userMsg }
        ],
        max_tokens: 350,
        temperature: 0.7
      }),
      signal: AbortSignal.timeout(25000)
    });

    if (oResp.status === 429 && attempt === 0) {
      await new Promise(r => setTimeout(r, 3000));
      continue;
    }

    if (!oResp.ok) {
      lastError = 'openai_' + oResp.status;
      if (attempt === 0) { await new Promise(r => setTimeout(r, 2000)); continue; }
      break;
    }

    const aiData = await oResp.json();
    aiResponse = aiData.choices[0].message.content.trim();
    break;
  } catch (e) {
    lastError = e.message;
    if (attempt === 0) { await new Promise(r => setTimeout(r, 2000)); continue; }
  }
}

// Fallback message based on Be Healthy manual
if (!aiResponse) {
  aiResponse = `Oi ${displayName}! 😊 Vi que você comentou no nosso Reel sobre mudança — e que bom que esse conteúdo te tocou!\n\nAqui no Instituto Be Healthy, acreditamos que toda transformação começa com uma decisão. Me conta: o que você mais gostaria de mudar hoje na sua saúde ou no seu corpo?\n\nO Dr. Felipe tem protocolos exclusivos e personalizados, com mais de 95% de satisfação. Posso te contar mais sobre como funciona! 💚`;
}

return [{ json: { ...data, dmMessage: aiResponse, _aiError: lastError } }];

// Send DM via Instagram Graph API
const data = $input.first().json;
const prevData = $('Generate MUDANÇA DM').first().json;

if (!prevData.senderId || !$env.META_ACCESS_TOKEN) {
  return [{ json: { ...prevData, igReplyStatus: 'no_meta_token_or_sender' } }];
}

try {
  const r = await fetch('https://graph.instagram.com/v21.0/me/messages', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + $env.META_ACCESS_TOKEN,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      recipient: { id: prevData.senderId },
      message: { text: prevData.dmMessage }
    }),
    signal: AbortSignal.timeout(15000)
  });

  if (!r.ok) {
    const errText = await r.text();
    return [{ json: { ...prevData, igReplyStatus: 'failed', igError: r.status + ': ' + errText } }];
  }

  return [{ json: { ...prevData, igReplyStatus: 'sent' } }];
} catch (e) {
  return [{ json: { ...prevData, igReplyStatus: 'error', igError: e.message } }];
}
